// single-item input: one form submission, one comparison.
//
// The form is read by name rather than off $input - `Settings` sits between the
// two and a Set node replaces the item, so $input here is the configuration.
const f = $('Ask For Both Sites').first().json;

function host(v) {
  return String(v == null ? '' : v)
    .trim()
    .toLowerCase()
    .replace(/^https?:\/\//, '')
    .replace(/^www\./, '')
    .replace(/[\/?#].*$/, '');
}

const yours = host(f['Your website']);
const theirs = host(f['Competitor website']);

if (!yours || yours.indexOf('.') < 0) throw new Error('Enter your site as a domain, for example acme.com');
if (!theirs || theirs.indexOf('.') < 0) throw new Error('Enter the competitor as a domain, for example rival.com');
if (yours === theirs) throw new Error('Both fields are the same domain. The gap between a site and itself is empty.');

// Two items, one per site, so both robots files are fetched by one node and the
// rest of the workflow never has to care which side it is looking at.
return [
  { json: { side: 'yours', domain: yours, url: 'https://' + yours + '/robots.txt' } },
  { json: { side: 'theirs', domain: theirs, url: 'https://' + theirs + '/robots.txt' } },
];

// Where a sitemap lives is not guessable, and guessing wrong fails quietly.
// Measured 2026-08-28: `pipedrive.com/sitemap.xml` answered HTTP 200 with 71 KB
// of Next.js HTML and no <loc> at all, while its robots.txt named
// `sitemap-index.xml`. Three of four domains checked named their sitemap in
// robots, and all three used a different filename - `sitemap-index.xml`,
// `sitemap_index.xml`, `sitemap-index.xml`. HubSpot named none and its
// `/sitemap.xml` is real. So robots is asked first and the guesses are a
// fallback, not the plan.
const sides = $('Read The Request').all().map(function (i) { return i.json; });
const cfg = $('Settings').first().json;
const perSite = Math.max(1, Number(cfg.max_sitemaps_per_site) || 3);

const GUESSES = ['/sitemap.xml', '/sitemap_index.xml', '/sitemap-index.xml'];
const out = [];

$input.all().forEach(function (item, idx) {
  const side = sides[idx] || {};
  const raw = item.json;
  const text = String(typeof raw === 'string' ? raw : (raw.data || raw.body || ''));

  if (/rate limit has been applied/i.test(text)) {
    throw new Error('Bright Data rate-limited the robots fetch. Try again in a few seconds.');
  }

  const declared = [];
  const lines = text.split('\n');
  lines.forEach(function (line) {
    const m = line.match(/^\s*sitemap\s*:\s*(\S+)\s*$/i);
    if (m) declared.push(m[1]);
  });

  // Prefer a sitemap that looks like it indexes content over one that indexes
  // images or news - a picture has no topic.
  const ranked = declared.filter(function (u) {
    return !/(image|video|news|category|tag)[-_]?sitemap/i.test(u);
  });
  const chosen = (ranked.length ? ranked : declared).slice(0, perSite);

  const urls = chosen.length
    ? chosen
    : GUESSES.slice(0, 1).map(function (g) { return 'https://' + side.domain + g; });

  urls.forEach(function (u) {
    out.push({ json: {
      side: side.side,
      domain: side.domain,
      url: u,
      from_robots: chosen.length > 0,
      guesses_left: chosen.length ? [] : GUESSES.slice(1).map(function (g) { return 'https://' + side.domain + g; }),
    }});
  });
});

if (!out.length) {
  throw new Error('Neither robots.txt could be read. Check both domains and that the Web Unlocker zone is active.');
}
return out;

// Two things are checked before anything is parsed, and both were measured.
//
//   * Is it XML at all? A 200 carrying `<!DOCTYPE html>` is a soft 404 dressed
//     as a sitemap, and counting <loc> in it returns zero - which reads exactly
//     like a competitor who has published nothing.
//   * Is it an index rather than a list? Most are. This node therefore emits a
//     *frontier* of sitemaps still to open, alongside the pages it already
//     found, and the loop below walks down until the frontier is empty.
const asked = $('Find The Sitemaps').all().map(function (i) { return i.json; });
const cfg = $('Settings').first().json;

const pages = [];
const frontier = [];
const notes = [];

$input.all().forEach(function (item, idx) {
  const meta = asked[idx] || {};
  const raw = item.json;
  const xml = String(typeof raw === 'string' ? raw : (raw.data || raw.body || ''));

  if (/rate limit has been applied/i.test(xml)) {
    throw new Error('Bright Data rate-limited a sitemap fetch. Lower the batch size and try again.');
  }

  if (!/<urlset|<sitemapindex/i.test(xml)) {
    notes.push(meta.side + ': ' + meta.url + ' did not return XML (' + xml.slice(0, 40).replace(/\s+/g, ' ') + '...)');
    return;
  }

  const found = [];
  [...xml.matchAll(/<loc>\s*([^<\s]+)\s*<\/loc>/gi)].forEach(function (m) { found.push(m[1]); });

  if (/<sitemapindex/i.test(xml)) {
    found.forEach(function (u) { frontier.push({ side: meta.side, domain: meta.domain, url: u }); });
  } else {
    found.forEach(function (u) { pages.push({ side: meta.side, url: u }); });
  }
});

return [{ json: { frontier: frontier, pages: pages, depth: 1, notes: notes } }];

// single-item input: one frontier, walked one level at a time.
//
// The filtering happens here rather than where the frontier was built, because
// it has to be applied at every level and the cap has to be per site. Measured
// 2026-08-28 with the naive version: pipedrive's index was walked into
// `cs-landing-page-images.xml` and `cs-landing-page-videos.xml` - a picture has
// no topic, and `cs` is a Czech locale, so the comparison was being run against
// two sitemaps of images in a language nobody asked about.
const cfg = $('Settings').first().json;
const perSite = Math.max(1, Number(cfg.max_child_sitemaps) || 6);
const j = $input.first().json;

const NOT_CONTENT = /(image|video|news|author|tag|category)[-_]?sitemaps?|sitemaps?[-_]?(image|video|news)|[-_](images?|videos?)\.xml/i;
const IS_CONTENT = /(post|article|blog|page|resource|guide|learn)/i;

// The same locale rule the comparison uses further down, applied here so the
// walk never spends its budget on a translation. Measured 2026-08-29 without
// it: pipedrive's index was walked into `cs-landing-page-*.xml`, every URL
// underneath was a `/cs/` Czech page, and the comparison then ran with 3,243
// of their pages against *zero* of yours - which produces a ranked list of 663
// gaps that are all simply "pages we did not look at".
const LOCALES = ('af ar bg bn ca cs da de el es et fa fi fr he hi hr hu id is it ja ka ko lt lv '
  + 'ms nb nl no pl pt ro ru sk sl sr sv th tr uk vi zh').split(' ');
const LOCALESET = {};
LOCALES.forEach(function (l) { LOCALESET[l] = true; });

function localeUrl(url) {
  const path = String(url).replace(/^https?:\/\/[^/]+/, '').split('?')[0];
  const segs = path.split('/').filter(Boolean);
  for (let i = 0; i < segs.length; i++) {
    const seg = segs[i].toLowerCase();
    if (seg === 'lang') return true;
    const bare = seg.replace(/\.xml$/, '');
    // `/cs/sitemap.xml` and `cs-landing-page.xml` are both a translation.
    if (LOCALESET[bare.split(/[-_]/)[0]] && (bare.length === 2 || bare.indexOf('-') > 0 || bare.indexOf('_') > 0)) return true;
  }
  return false;
}

const bySide = {};
(j.frontier || []).forEach(function (c) {
  if (NOT_CONTENT.test(c.url)) return;
  if (localeUrl(c.url)) return;
  if (!bySide[c.side]) bySide[c.side] = [];
  bySide[c.side].push(c);
});

const out = [];
Object.keys(bySide).forEach(function (side) {
  const all = bySide[side];
  // Content-looking children first, but never *only* them - a site whose
  // sitemaps are named `1.xml`, `2.xml` would otherwise come back empty.
  const preferred = all.filter(function (c) { return IS_CONTENT.test(c.url); });
  const ordered = preferred.concat(all.filter(function (c) { return !IS_CONTENT.test(c.url); }));
  ordered.slice(0, perSite).forEach(function (c) { out.push(c); });
});

if (!out.length) {
  throw new Error('The IF sent this branch an empty frontier, which should be impossible. Check the condition on More Levels To Walk?');
}
return out;

// One level walked. Everything found so far travels forward on the item, so the
// next pass round the loop can add to it - a Code node cannot see its own
// earlier runs, and the accumulator has to live somewhere.
//
// Three levels is not a theoretical depth. Measured 2026-08-28: monday.com's
// robots names `sitemap_index.xml`, that index names `blog/sitemap_index.xml`,
// and *that* names `post-sitemap.xml` through `post-sitemap4.xml`. A walk that
// stops after one level finds no pages at all on one of the most ordinary
// marketing sites there is.
const asked = $('Pick The Next Sitemaps').all().map(function (i) { return i.json; });
const prev = $('Read The Sitemaps').first().json;
const carried = $('More Levels To Walk?').first().json;

const pages = (carried.pages || prev.pages || []).slice();
const frontier = [];
const notes = (carried.notes || []).slice();

$input.all().forEach(function (item, idx) {
  const meta = asked[idx] || {};
  const raw = item.json;
  const xml = String(typeof raw === 'string' ? raw : (raw.data || raw.body || ''));

  if (/rate limit has been applied/i.test(xml)) {
    throw new Error('Bright Data rate-limited a sitemap fetch. Lower max_child_sitemaps and try again.');
  }
  if (!/<urlset|<sitemapindex/i.test(xml)) {
    notes.push(meta.side + ': ' + meta.url + ' did not return XML');
    return;
  }

  const found = [];
  [...xml.matchAll(/<loc>\s*([^<\s]+)\s*<\/loc>/gi)].forEach(function (m) { found.push(m[1]); });

  if (/<sitemapindex/i.test(xml)) {
    found.forEach(function (u) { frontier.push({ side: meta.side, domain: meta.domain, url: u }); });
  } else {
    found.forEach(function (u) { pages.push({ side: meta.side, url: u }); });
  }
});

return [{ json: {
  frontier: frontier,
  pages: pages,
  depth: (Number(carried.depth) || 1) + 1,
  notes: notes,
} }];

// The comparison is on slug words, and that choice is what makes this cheap
// enough to run on a whim: two sitemaps are two requests and tell you which
// subjects exist on one site and not the other. Reading 7,825 pages to find out
// would be a different product.
const cfg = $('Settings').first().json;
const req = $('Read The Request').all().map(function (i) { return i.json; });
const flat = $('Read The Sitemaps').first().json;

// Every page URL found, from whichever branch produced it.
let all = (flat.pages || []).slice();
$input.all().forEach(function (i) {
  const extra = (i.json && i.json.pages) || [];
  all = all.concat(extra);
});

const minSize = Math.max(2, Number(cfg.min_topic_size) || 3);
const topN = Math.max(1, Number(cfg.max_gaps_to_read) || 5);

// Words that appear in a slug on every site in the world and mean nothing about
// what a page is about.
const STOP = ('the a an and or of for to in on with without your you our we is are how what why when '
  + 'best top guide guides tips ultimate complete free vs versus review reviews blog post posts article '
  + 'articles page pages resources resource new update updated 2019 2020 2021 2022 2023 2024 2025 2026 '
  + 'com www html index home about contact privacy terms login signup pricing').split(' ');
const STOPSET = {};
STOP.forEach(function (w) { STOPSET[w] = true; });

// Measured on the first live run: comparing monday.com (6,372 URLs) against
// pipedrive.com (969) ranked `datenschutz`, `sicherheit` and `lang` at the top,
// because a site that publishes in fourteen languages has fourteen URLs for
// every page and the locale words outnumber every real subject. A gap analysis
// across two languages is not a gap analysis, so only the default-language URLs
// are counted, on both sides.
const LOCALES = ('af ar bg bn ca cs da de el en es et fa fi fr he hi hr hu id is it ja ka ko lt lv '
  + 'ms nb nl no pl pt ro ru sk sl sr sv th tr uk vi zh').split(' ');
const LOCALESET = {};
LOCALES.forEach(function (l) { LOCALESET[l] = true; });

function localised(url) {
  const path = String(url).replace(/^https?:\/\/[^/]+/, '').split('?')[0];
  const segs = path.split('/').filter(Boolean);
  for (let i = 0; i < segs.length; i++) {
    const seg = segs[i].toLowerCase();
    if (seg === 'lang') return true;
    // `de`, `pt-br`, `zh_TW` - a two-letter segment on a marketing site is a
    // language nine times out of ten, and the tenth is not worth the noise.
    const base = seg.split(/[-_]/)[0];
    if (base.length === 2 && LOCALESET[base] && base !== 'en') return true;
  }
  return false;
}

function tokens(url) {
  let path = String(url).replace(/^https?:\/\/[^/]+/, '').split('?')[0].split('#')[0];
  path = path.replace(/\.(html?|php|aspx?)$/i, '');
  return path
    .split(/[\/\-_.]+/)
    .map(function (t) { return t.toLowerCase().trim(); })
    .filter(function (t) {
      if (t.length < 4 || t.length > 24) return false;
      if (STOPSET[t]) return false;
      if (/^\d+$/.test(t)) return false;   // ids and dates are not topics
      return true;
    });
}

const mine = {};
const theirs = {};
const examples = {};

let dropped_locale = 0;

all.forEach(function (p) {
  if (localised(p.url)) { dropped_locale += 1; return; }
  const bag = p.side === 'yours' ? mine : theirs;
  const seen = {};
  tokens(p.url).forEach(function (t) {
    if (seen[t]) return;      // a word twice in one URL is still one page
    seen[t] = true;
    bag[t] = (bag[t] || 0) + 1;
    if (p.side === 'theirs') {
      if (!examples[t]) examples[t] = [];
      if (examples[t].length < 4) examples[t].push(p.url);
    }
  });
});

const yourTotal = Object.keys(mine).length;
const theirTotal = Object.keys(theirs).length;

// A side with almost no URLs makes every subject on the other side look like a
// gap. Measured 2026-08-29: a walk that followed only pipedrive's Czech
// sitemaps left it with zero countable pages, and the report cheerfully ranked
// 663 "gaps" that were nothing of the kind. Refusing is the only honest answer,
// because the ranking below cannot be made meaningful by any amount of care.
const floor = Math.max(5, Number(cfg.min_urls_per_side) || 20);
const countable = { yours: 0, theirs: 0 };
all.forEach(function (p) { if (!localised(p.url)) countable[p.side] += 1; });
if (countable.yours < floor || countable.theirs < floor) {
  throw new Error('Not enough comparable pages: ' + countable.yours + ' from your site and ' +
    countable.theirs + ' from theirs, after setting aside ' + dropped_locale + ' translated pages. ' +
    'One of the sitemaps that was walked is probably a partial or translated one. ' +
    'Raise max_child_sitemaps so more of each index is followed, or point the form at the blog subdomain directly.');
}

if (!theirTotal) {
  throw new Error('No page URLs were found for the competitor once translated pages were set aside (' +
    dropped_locale + ' were). ' +
    (flat.notes && flat.notes.length ? flat.notes.join(' | ') : 'Their sitemap may be somewhere robots.txt does not name.'));
}

const gaps = Object.keys(theirs)
  .filter(function (t) { return theirs[t] >= minSize && !mine[t]; })
  .map(function (t) {
    return { topic: t, their_pages: theirs[t], your_pages: 0, examples: examples[t] || [] };
  })
  .sort(function (a, b) { return b.their_pages - a.their_pages; });

// A thin gap is still worth ranking, but only the top few are worth a request
// each - which is the whole cost of the run.
const toRead = gaps.slice(0, topN);

return [{ json: {
  your_domain: req[0] ? req[0].domain : '',
  their_domain: req[1] ? req[1].domain : '',
  urls_yours: all.filter(function (p) { return p.side === 'yours' && !localised(p.url); }).length,
  urls_theirs: all.filter(function (p) { return p.side === 'theirs' && !localised(p.url); }).length,
  urls_localised: dropped_locale,
  words_yours: yourTotal,
  words_theirs: theirTotal,
  gap_count: gaps.length,
  gaps: gaps.slice(0, 40),
  to_read: toRead,
  notes: flat.notes || [],
}}];

// single-item input: one comparison produces one queue.
const j = $input.first().json;
const list = j.to_read || [];

// The loop below must always receive at least one item or the branch ends and
// the report never runs. Two sites with no gap between them is a real and
// perfectly good outcome, so it travels as a marker rather than as silence.
if (!list.length) {
  return [{ json: { topic: '', url: '', nothing_to_read: true } }];
}
return list.map(function (g) {
  return { json: { topic: g.topic, their_pages: g.their_pages, url: g.examples[0] || '' } };
});

// One article per pass. The loop exists so that a run opens three pages at a
// time rather than twenty at once - the Web Unlocker answers a burst with a
// rate-limit sentence carrying HTTP 200, which retryOnFail never sees.
const asked = $input.all();
const out = [];

asked.forEach(function (item) {
  const raw = item.json;
  const text = String(typeof raw === 'string' ? raw : (raw.data || raw.body || ''));
  const src = $('Loop Over The Gaps').first().json;

  if (/rate limit has been applied/i.test(text)) {
    throw new Error('Bright Data rate-limited the article fetch. Lower max_gaps_to_read or the batch size on Fetch A Gap Article.');
  }

  const clean = text
    .replace(/!\[[^\]]*\]\([^)]*\)/g, ' ')
    .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

  // The first markdown heading is the headline on almost every article
  // template - but a heading is frequently a logo, so what is left after the
  // image syntax is stripped has to still look like words.
  let title = '';
  const h = clean.match(/^#{1,3}\s+(.+)$/m);
  if (h) title = h[1].replace(/\s+/g, ' ').trim();
  const letters = (title.match(/[A-Za-z]/g) || []).length;
  if (letters < 8) title = String(src.url || '').split('/').filter(Boolean).pop() || '';

  out.push({ json: {
    topic: src.topic,
    url: src.url,
    their_pages: src.their_pages,
    title: title,
    words: clean.split(/\s+/).length,
    extract: clean.slice(0, 2500),
  }});
});

return out;

// Everything the loop gathered, in one item, for one model call. Judging each
// article separately would cost five calls to answer one question.
const gapInfo = $('Find The Gaps').first().json;
const read = [];

// `Loop Over The Gaps` emits its accumulated items on the done output, so this
// reads what actually came back rather than what was queued.
$input.all().forEach(function (i) {
  const j = i.json || {};
  if (j.title || j.extract) read.push(j);
});

const brief = read.map(function (r, i) {
  return '### ' + (i + 1) + '. ' + r.topic + ' (' + r.their_pages + ' of their URLs)\n' +
    'Title: ' + r.title + '\n' +
    'URL: ' + r.url + '\n' +
    'Opening: ' + String(r.extract || '').slice(0, 1200);
}).join('\n\n');

return [{ json: Object.assign({}, gapInfo, {
  read_count: read.length,
  read: read,
  brief: brief || 'No articles were read - the two sites have no slug-level gap above the threshold.',
}) }];

// single-item input: one judgement covering every gap.
const pack = $('Collect What Came Back').first().json;
const raw = $input.first().json;
const answer = String(raw.text || raw.output || raw.response || '').trim();

const WORTH = { high: 1, medium: 1, low: 1 };
const byIndex = {};

// The model was asked for one pipe-delimited line per subject. Anything that
// does not parse is dropped rather than guessed at, and the count is reported -
// a row invented here would be indistinguishable from a finding.
answer.split('\n').forEach(function (line) {
  const parts = line.split('|').map(function (p) { return p.trim(); });
  if (parts.length < 5) return;
  const n = parseInt(parts[0].replace(/\D/g, ''), 10);
  if (!n) return;
  let worth = parts[3].replace(/^worth it:\s*/i, '').toLowerCase().trim();
  if (!WORTH[worth]) worth = 'medium';
  byIndex[n] = { subject: parts[1], angle: parts[2], worth: worth, why: parts.slice(4).join(' | ') };
});

const rows = pack.read.map(function (r, i) {
  const j = byIndex[i + 1] || {};
  return {
    checked_on: new Date().toISOString().slice(0, 10),
    your_site: pack.your_domain,
    their_site: pack.their_domain,
    topic: r.topic,
    subject: j.subject || r.topic,
    their_pages: r.their_pages,
    example_url: r.url,
    example_title: r.title,
    angle: j.angle || '',
    worth_it: j.worth || 'unrated',
    why: j.why || '',
  };
});

const unparsed = pack.read.length - Object.keys(byIndex).length;
const order = { high: 0, medium: 1, low: 2, unrated: 3 };
rows.sort(function (a, b) { return order[a.worth_it] - order[b.worth_it] || b.their_pages - a.their_pages; });

const lines = ['*Content gaps: ' + pack.their_domain + ' vs ' + pack.your_domain + '*',
  pack.urls_theirs + ' of their URLs against ' + pack.urls_yours + ' of yours' +
  (pack.urls_localised ? ' (' + pack.urls_localised + ' translated pages set aside)' : '') + '. ' +
  pack.gap_count + ' subject(s) they cover and you do not; the top ' + rows.length + ' were read.'];
rows.forEach(function (r) {
  lines.push('');
  lines.push('*' + r.subject + '* - ' + r.worth_it + ' - ' + r.their_pages + ' of their pages');
  if (r.angle) lines.push('Their angle: ' + r.angle);
  if (r.why) lines.push('_' + r.why + '_');
  lines.push(r.example_url);
});
if (unparsed > 0) lines.push('\n_' + unparsed + ' subject(s) came back unrated - the model did not answer in the expected form._');
if (pack.notes && pack.notes.length) lines.push('\n_Notes: ' + pack.notes.join(' | ') + '_');

const html = ['<h2>Content gaps: ' + pack.their_domain + ' vs ' + pack.your_domain + '</h2>',
  '<p>' + pack.urls_theirs + ' of their URLs against ' + pack.urls_yours + ' of yours. ' +
  pack.gap_count + ' subject(s) they cover and you do not.</p>',
  '<table border="1" cellpadding="6" cellspacing="0"><tr><th>Subject</th><th>Worth it</th><th>Their pages</th><th>Their angle</th><th>Example</th></tr>'];
rows.forEach(function (r) {
  html.push('<tr><td>' + r.subject + '</td><td>' + r.worth_it + '</td><td>' + r.their_pages +
    '</td><td>' + r.angle + '</td><td><a href="' + r.example_url + '">' + (r.example_title || 'open') + '</a></td></tr>');
});
html.push('</table>');

return [{ json: { rows: rows, message: lines.join('\n'), html: html.join(''), row_count: rows.length } }];
